import{_ as e,o as r,c as s,a0 as o}from"./chunks/framework.DScjKhBS.js";const m=JSON.parse('{"title":"Structured-Prompt-Driven Development (SPDD)","description":"Research microsite — synthesis of Thoughtworks’ SPDD method (Wei Zhang & Jessie Jie Xia), hosted by Martin Fowler. Governable, reviewable LLM-assisted delivery via versioned structured prompts and the REASONS Canvas.","frontmatter":{"layout":"doc","title":"Structured-Prompt-Driven Development (SPDD)","description":"Research microsite — synthesis of Thoughtworks’ SPDD method (Wei Zhang & Jessie Jie Xia), hosted by Martin Fowler. Governable, reviewable LLM-assisted delivery via versioned structured prompts and the REASONS Canvas."},"headers":[],"relativePath":"reports/structured-prompt-driven/index.md","filePath":"reports/structured-prompt-driven/index.md"}'),a={name:"reports/structured-prompt-driven/index.md"};function n(i,t,d,p,l,c){return r(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="structured-prompt-driven-development-spdd" tabindex="-1">Structured-Prompt-Driven Development (SPDD) <a class="header-anchor" href="#structured-prompt-driven-development-spdd" aria-label="Permalink to &quot;Structured-Prompt-Driven Development (SPDD)&quot;">​</a></h1><p><strong>Research synthesis.</strong> This microsite summarises <a href="https://martinfowler.com/articles/structured-prompt-driven/" target="_blank" rel="noreferrer">Structured-Prompt-Driven Development (SPDD)</a> — a Thoughtworks Global IT Services practice for turning LLM coding assistance from individual speed into <strong>governable, reviewable, reusable</strong> team delivery. The primary article is by <strong>Wei Zhang</strong> and <strong>Jessie Jie Xia</strong>, published on <strong>Martin Fowler’s site</strong> (28 April 2026).</p><p><strong>Core claim:</strong> Treat <strong>structured prompts as first-class artifacts</strong> in version control — aligned with code through a defined workflow — so intent, boundaries, and implementation stay traceably linked.</p><hr><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Primary source</strong></td><td><a href="https://martinfowler.com/articles/structured-prompt-driven/" target="_blank" rel="noreferrer">martinfowler.com/articles/structured-prompt-driven/</a></td></tr><tr><td><strong>CLI workflow</strong></td><td><a href="https://github.com/gszhangwei/open-spdd" target="_blank" rel="noreferrer">open-spdd</a> (<code>openspdd</code>)</td></tr><tr><td><strong>Example codebase</strong></td><td>Billing-engine walkthrough linked from the article</td></tr><tr><td><strong>Named skills</strong></td><td>Abstraction first, Alignment, Iterative review</td></tr></tbody></table><hr><h2 id="microsite-sections" tabindex="-1">Microsite sections <a class="header-anchor" href="#microsite-sections" aria-label="Permalink to &quot;Microsite sections&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./reports/structured-prompt-driven/01-spdd-and-reasons.html">What SPDD is &amp; the REASONS Canvas</a></td><td>Problem framing, canvas dimensions, prompt-as-spec</td></tr><tr><td><a href="./reports/structured-prompt-driven/02-openspdd-and-workflow.html">Workflow &amp; openspdd commands</a></td><td>Closed loop vs one-way pipeline, command cheat sheet, SPDD vs spec-driven development</td></tr><tr><td><a href="./reports/structured-prompt-driven/03-case-study-billing-engine.html">Case study: billing engine</a></td><td>Condensed walkthrough — analysis → Canvas → code → tests</td></tr><tr><td><a href="./reports/structured-prompt-driven/04-skills-fitness-and-trade-offs.html">Skills, fitness &amp; trade-offs</a></td><td>When SPDD pays off, ROI vs upfront cost</td></tr><tr><td><a href="./reports/structured-prompt-driven/05-sources-and-next-steps.html">Sources &amp; tooling</a></td><td>Quotes, acknowledgements, links</td></tr></tbody></table><p>Start with <a href="./reports/structured-prompt-driven/01-spdd-and-reasons.html">What SPDD is &amp; the REASONS Canvas</a> if you are new to the method.</p><hr><h2 id="one-line-positioning" tabindex="-1">One-line positioning <a class="header-anchor" href="#one-line-positioning" aria-label="Permalink to &quot;One-line positioning&quot;">​</a></h2><p>SPDD is closest to <strong>spec-anchored</strong> AI delivery: the structured prompt is the maintained record of intent; <strong>openspdd</strong> automates repeatable steps so prompts are not trapped in chat threads.</p><hr><p><em>Synthesis for Elixirr Digital research navigation. For diagrams, footnotes, and full narrative, use the <a href="https://martinfowler.com/articles/structured-prompt-driven/" target="_blank" rel="noreferrer">original article</a>.</em></p>',15)])])}const u=e(a,[["render",n]]);export{m as __pageData,u as default};
